<script setup lang="ts">
import {ref} from 'vue'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
const api=createProtectedClient(),id=ref(''),row=ref<components['schemas']['AppliedTreatmentView']|null>(null),etag=ref(''),price=ref(''),reason=ref(''),confirmed=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref('');let pending:PreparedCommand|undefined
async function read(){if(pending)return;busy.value=true;error.value='';confirmed.value=false;try{const result=await api.getResource<components['schemas']['AppliedTreatmentView']>(`/api/v1/applied-treatments/${encodeURIComponent(id.value)}`);row.value=result.data;etag.value=result.etag??'';price.value=result.data.unit_price}catch(failure){row.value=null;error.value=failure instanceof ApiFailure?`无法核验当前记录：${failure.message}`:'暂未取得当前记录。'}finally{busy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';try{const result=await api.execute<components['schemas']['AppliedTreatmentView']>(pending);notice.value=`价格纠错已保存，当前小计 ${result.data.subtotal}。`;pending=undefined;unknown.value=false;await read()}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;error.value=failure instanceof ApiFailure?(failure.status===412?'价格已变化，请重新读取核对。':`未完成：${failure.message}`):'纠错未完成。';if(failure instanceof ApiFailure && [401,403].includes(failure.status))row.value=null}}finally{busy.value=false}}
async function save(){if(pending || !row.value || !confirmed.value)return;pending=prepareCommand('correctTreatmentPrice','POST',`/api/v1/applied-treatments/${row.value.applied_treatment_id}/correct-price`,{unit_price:price.value,reason:reason.value,verification_reference:row.value.etag},etag.value);await execute()}
async function query(){if(!pending)return;try{const receipt=await api.requestResult<{status:string}>(pending);notice.value=receipt.status==='SUCCEEDED'?'原请求已成功，请重新确认取得授权结果。':'尚未确认成功，请保留当前页面。'}catch{error.value='暂未取得当前授权回执。'}}
</script>
<template><section><h1>治疗价格纠错</h1><p>需单独的价格纠错权限；核实当前实际记录与依据后办理，旧新价格及原因保留审计。</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询办理进度</button><button :disabled="busy" @click="execute">重新确认办理结果</button></div><form @submit.prevent="read"><fieldset :disabled="busy || unknown"><label>实际治疗记录 ID<input v-model="id" required pattern="[1-9][0-9]*" @input="row=null;confirmed=false"></label><button>读取并核验当前价格</button></fieldset></form><section v-if="row"><p>就诊 {{row.appointment_id}} · 实施牙医 {{row.dentist_id}} · {{row.standard_units}} 单位 · 当前单价 {{row.unit_price}} · 小计 {{row.subtotal}}</p><form @submit.prevent="save"><fieldset :disabled="busy || unknown"><label>核实后的单价<input v-model="price" required inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"></label><label>价格纠错依据与原因<input v-model="reason" required maxlength="255"></label><label><input v-model="confirmed" type="checkbox" required>已核实当前记录及本次价格纠错依据</label><button :disabled="!confirmed || !etag">确认授权价格纠错</button></fieldset></form></section></section></template>
<style scoped>fieldset{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:20px 0;padding:18px}label{display:grid;gap:7px}input{padding:9px;border:1px solid #bacdc5;border-radius:5px}button{padding:10px 16px}</style>
